package com.mewcode.tool;
import com.mewcode.tool.impl.DiffUtil;import java.nio.charset.StandardCharsets;import java.nio.file.Files;import java.nio.file.Path;import java.security.MessageDigest;import java.util.HexFormat;import java.util.Map;
public record MutationPreview(Path path,String before,String after,String diff,String beforeHash,String diffHash){
 public static MutationPreview prepare(String tool,Map<String,Object>a){try{if(!"WriteFile".equals(tool)&&!"EditFile".equals(tool))return null;Path p=Path.of(String.valueOf(a.get("file_path"))).toAbsolutePath().normalize();String before=Files.exists(p)?Files.readString(p):"";String after;if("WriteFile".equals(tool))after=String.valueOf(a.getOrDefault("content",""));else{String old=String.valueOf(a.getOrDefault("old_string",""));String next=String.valueOf(a.getOrDefault("new_string",""));int first=before.indexOf(old);if(first<0||first!=before.lastIndexOf(old))throw new IllegalArgumentException("old_string must occur exactly once");after=before.replace(old,next);}String diff=DiffUtil.buildDiff(before,after).text();return new MutationPreview(p,before,after,diff,hash(before),hash(diff));}catch(Exception e){throw new IllegalArgumentException("Cannot prepare mutation: "+e.getMessage(),e);}}
 public void verifyCurrent(){try{String current=Files.exists(path)?Files.readString(path):"";if(!hash(current).equals(beforeHash))throw new java.util.ConcurrentModificationException("target changed after approval");String nextDiff=DiffUtil.buildDiff(current,after).text();if(!hash(nextDiff).equals(diffHash))throw new java.util.ConcurrentModificationException("diff changed after approval");}catch(java.io.IOException e){throw new IllegalStateException(e);}}
 private static String hash(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
}
